#include <algorithm>
#include <iostream>
#include <vector>

struct Request { int priority; char name; };

int main() {
  std::vector<Request> rows{{2, 'A'}, {1, 'B'}, {2, 'C'}, {1, 'D'}};
  std::stable_sort(rows.begin(), rows.end(),
      [](const Request& a, const Request& b) { return a.priority < b.priority; });
  for (const auto& row : rows) std::cout << row.name;
}
